assert.equal(typeof mod.connectEffect, 'function', 'export connectEffect');
let listeners = [];
const bus = {
  subscribe(fn) { listeners.push(fn); return () => { listeners = listeners.filter((l) => l !== fn); }; },
  emit(v) { for (const l of listeners) l(v); },
};
const got = [];
const cleanup = mod.connectEffect(bus, (v) => got.push(v));
assert.equal(typeof cleanup, 'function', 'the effect must RETURN the cleanup function');
bus.emit('hello');
assert.deepStrictEqual(got, ['hello']);
cleanup();
bus.emit('after');
assert.deepStrictEqual(got, ['hello'], 'after cleanup, no more messages may arrive');
assert.equal(listeners.length, 0);

let unsubCalls = 0;
const bus = { subscribe() { return () => { unsubCalls++; }; } };
const cleanup = mod.connectEffect(bus, () => {});
assert.equal(unsubCalls, 0, 'setup must not unsubscribe immediately (return unsub, not unsub())');
cleanup();
assert.equal(unsubCalls, 1);

assert.equal(typeof mod.startTicker, 'function', 'export startTicker');
const calls = [];
let nextId = 7;
const cleared = [];
const clock = {
  setInterval(fn, ms) { calls.push({ fn, ms }); return nextId++; },
  clearInterval(id) { cleared.push(id); },
};
const tick = () => {};
const cleanup = mod.startTicker(clock, tick);
assert.equal(calls.length, 1, 'exactly one interval must start');
