let state = 0;
const pending = [];
function setState(update) {
  pending.push(update);
}
// a "handler" that closed over state === 0
const count = state;
setState(count + 1);
setState(count + 1);
setState((prev) => prev + 1);
// "commit" the batch the way React does
for (const u of pending) {
  state = typeof u === 'function' ? u(state) : u;
}
console.log(state);

let state = 'idle';
const queue = ['loading', (prev) => prev + '!', 'done'];
for (const u of queue) {
  state = typeof u === 'function' ? u(state) : u;
}
console.log(state);

