  // your code here
}

bootforge/react-state/state-mechanics/us.solution:
export function simulateBatch(initial, updates) {
  let pending = initial;
  let changed = false;
  for (const u of updates) {
    const next = typeof u === 'function' ? u(pending) : u;
    if (!Object.is(next, pending)) changed = true;
    pending = next;
  }
  return { state: pending, renders: changed ? 1 : 0 };
}

