bootforge/react-state/state-mechanics/im.solution:
export function mergeById(local, server) {
  const updated = local.map((item) => {
    const fresh = server.find((s) => s.id === item.id);
    return fresh ? fresh : item;
  });
  const localIds = new Set(local.map((i) => i.id));
  const added = server.filter((s) => !localIds.has(s.id));
  return [...updated, ...added];
}

