bootforge/react-state/state-mechanics/re.solution:
export function cartReducer(state, action) {
  switch (action.type) {
    case 'ADD_ITEM': {
      const exists = state.some((l) => l.id === action.id);
      if (!exists) return [...state, { id: action.id, qty: action.qty }];
      return state.map((l) => (l.id === action.id ? { ...l, qty: l.qty + action.qty } : l));
    }
    case 'REMOVE_ITEM':
      return state.filter((l) => l.id !== action.id);
    case 'SET_QTY': {
      if (action.qty <= 0) return state.filter((l) => l.id !== action.id);
      return state.map((l) => (l.id === action.id ? { ...l, qty: action.qty } : l));
    }
    case 'CLEAR':
      return [];
    default:
      return state;
  }
}

