export function wizardReducer(state, action) {
  switch (action.type) {
    case 'NEXT':
      return { ...state, step: Math.min(2, state.step + 1) };
    case 'BACK':
      return { ...state, step: Math.max(0, state.step - 1) };
    case 'SET_FIELD':
      return { ...state, data: { ...state.data, [action.field]: action.value } };
    case 'RESET':
      return { step: 0, data: {} };
    default:
      return state;
  }
}

