bootforge/react-state/state-mechanics/re.solution:
export function tabsReducer(state, action) {
  switch (action.type) {
    case 'OPEN_TAB': {
      const open = state.open.includes(action.id) ? state.open : [...state.open, action.id];
      return { open, active: action.id };
    }
    case 'SELECT_TAB':
      return state.open.includes(action.id) ? { ...state, active: action.id } : state;
    case 'CLOSE_TAB': {
      const open = state.open.filter((id) => id !== action.id);
      const active =
        state.active === action.id ? (open.length ? open[open.length - 1] : '') : state.active;
      return { open, active };
    }
    default:
      return state;
  }
}

