bootforge/react-state/state-mechanics/re.solution:
export function withUndo(reducer, initial) {
  return function wrapped(state, action) {
    if (action.type === 'UNDO') {
      if (state.past.length === 0) return state;
      return {
        past: state.past.slice(0, -1),
        present: state.past[state.past.length - 1],
      };
    }
    const next = reducer(state.present, action);
    if (Object.is(next, state.present)) return state;
    return { past: [...state.past, state.present], present: next };
  };
}

