export function memoizeLast(fn) {
  let has = false;
  let lastArg;
  let lastResult;
  return function (arg) {
    if (has && Object.is(arg, lastArg)) return lastResult;
    lastResult = fn(arg);
    lastArg = arg;
    has = true;
    return lastResult;
  };
}

