export function searchView(state) {
  const q = state.query.toLowerCase();
  const matching = state.products.filter((p) => p.name.toLowerCase().includes(q));
  const sorted = [...matching].sort((a, b) =>
    state.sortDir === 'desc' ? b.price - a.price : a.price - b.price
  );
  const total = sorted.length;
  const pageCount = Math.max(1, Math.ceil(total / state.perPage));
  const page = Math.min(pageCount, Math.max(1, state.page));
  const start = (page - 1) * state.perPage;
  return { items: sorted.slice(start, start + state.perPage), total, pageCount, page };
}

