export function runEffects(prevState, effects) {
  const ran = [];
  const nextState = [];
  effects.forEach((e, i) => {
    const prevDeps = prevState === null ? null : prevState[i];
    const run =
      e.deps === null ||
      prevDeps === null ||
      !e.deps.every((v, j) => Object.is(v, prevDeps[j]));
    if (run) ran.push(i);
    nextState.push(e.deps);
  });
  return { ran, nextState };
}

