export function createBus() {
  const listeners = [];
  // your code here: return { subscribe, emit, listenerCount }
}

bootforge/react-state/effects-and-data/c.solution:
export function createBus() {
  const listeners = [];
  return {
    subscribe(fn) {
      listeners.push(fn);
      let active = true;
      return () => {
        if (!active) return;
        active = false;
        const i = listeners.indexOf(fn);
        if (i !== -1) listeners.splice(i, 1);
      };
    },
    emit(value) {
      for (const l of [...listeners]) l(value);
    },
    listenerCount() {
      return listeners.length;
    },
  };
}

