bootforge/react-state/effects-and-data/c.solution:
export function createEffectManager(setup) {
  let mounted = false;
  let lastDep;
  let cleanup;
  const runCleanup = () => {
    if (typeof cleanup === 'function') cleanup();
    cleanup = undefined;
  };
  return {
    render(dep) {
      if (mounted && Object.is(dep, lastDep)) return;
      if (mounted) runCleanup();
      cleanup = setup(dep);
      lastDep = dep;
      mounted = true;
    },
    unmount() {
      if (!mounted) return;
      runCleanup();
      mounted = false;
    },
  };
}

