export function createSearch(fetcher, onResult) {
  let latest = 0;
  return {
    async search(query) {
      const id = ++latest;
      try {
        const results = await fetcher(query);
        if (id !== latest) return;
        onResult(query, results);
      } catch {
        if (id !== latest) return;
        onResult(query, null);
      }
    },
  };
}

