export function appReducer(state, action) {
  switch (action.type) {
    case 'SET_QUERY':
      return { ...state, query: action.query };
    case 'ADD_ITEM':
      return { ...state, items: [...state.items, action.item] };
    default:
      return state;
  }
}

export function App(state, dispatch) {
  const q = state.query.toLowerCase();
  const visible = state.items.filter((i) => i.toLowerCase().includes(q));
  return {
    type: 'div',
    props: {},
    children: [
      {
        type: 'input',
        props: {
          value: state.query,
          onInput: (text) => dispatch({ type: 'SET_QUERY', query: text }),
        },
        children: [],
      },
      {
        type: 'ul',
        props: {},
        children: visible.map((item) => ({ type: 'li', props: {}, children: [item] })),
      },
    ],
  };
}
